use verus::prelude::*;

verus! {

/// Given two arrays `a` and `b` sorted in non-decreasing order,
/// sizes `n_a` and `n_b`, and selection indices `k` and `m`,
/// determine if a[k-th element (1-based) in `a`] < b[(m-th from end)].
/// Return "YES" if true, else "NO".
fn solve(
    n_a: i8, n_b: i8,
    k: i8, m: i8,
    a: Vec<i8>, b: Vec<i8>
) -> &'static str
    requires n_a >= 1 && n_b >= 1,
    requires a.len() == n_a as usize,
    requires b.len() == n_b as usize,
    requires 1 <= k && k <= n_a,
    requires 1 <= m && m <= n_b,
    requires is_sorted_non_decreasing(&a),
    requires is_sorted_non_decreasing(&b),
    ensures |result| 
        (result == "YES") == (a[(k-1) as usize] < b[(n_b - m) as usize]),
{
    // Compute indices (convert 1-based to 0-based)
    let a_idx = (k - 1) as usize;
    let b_idx = (n_b - m) as usize;

    if a[a_idx] < b[b_idx] {
        "YES"
    } else {
        "NO"
    }
}

/// Helper spec-function to assert sorted non-decreasing property
proof fn is_sorted_non_decreasing(arr: &Vec<i8>) -> bool {
    forall(|i: int, j: int| (0 <= i && i < j && j < arr.len() as int) ==> arr[i as usize] <= arr[j as usize])
}

}